parameters.jsCode:
// Récupérer tous les items
const items = $input.all();

// Extraire les résultats des webhooks (2 premiers items ont body.result)
const webhookResults = items
  .filter(item => item.json.body && item.json.body.result)
  .map(item => item.json.body.result);

// Identifier chaque source par les champs présents
const soundcloudData = webhookResults.find(data => data.scFollowers !== undefined) || {};
const beatportData = webhookResults.find(data => data.isActive !== undefined) || {};
const bandcampData = webhookResults.find(data => data.vinyle !== undefined) || {};

// Récupérer le nom du label depuis les metadata (items qui ont labelName)
const metadataItem = items.find(item => item.json.labelName);
const labelName = metadataItem ? metadataItem.json.labelName : "Unknown";

// Retourner l'objet structuré
return {
  name: labelName,
  soundcloud: soundcloudData,
  beatport: beatportData,
  bandcamp: bandcampData
};

